using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ReductionAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Reduction Action")]
public class ReductionAction : ChooseCorruptPurifyDieAction
{
	[Header("Action Specifics")]
	[SerializeField]
	protected int finalValue;

	[SerializeField]
	protected BattleActionInteractionEnum battleActionInteractionEnum;

	[SerializeField]
	protected PurifyAction purifyAction;

	[SerializeField]
	protected OmenLogic targetToPurifyLogic;

	[SerializeField]
	private bool disablePurificationMultiplier;

	[SerializeField]
	[HideIf("disablePurificationMultiplier")]
	private int purificationMultiplier = 1;

	[SerializeField]
	private bool disablePurificationToPickedDice;

	[SerializeField]
	[HideIf("disablePurificationToPickedDice")]
	private bool purificationToPickedDice;

	[SerializeField]
	private bool allEnemyDice;

	public int FinalValue => finalValue;

	public PurifyAction PurifyAction => purifyAction;

	public int PurificationMultiplier => purificationMultiplier;

	public override void Cast(GameObject source)
	{
		if (diceList.Count == 0)
		{
			if (allEnemyDice)
			{
				diceList.AddRange(ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.GetEnemiesDiceInstances());
				DefaultCast(goBackToDiceTray: false, null, source);
				return;
			}
			InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
			{
				for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
				{
					diceList.Add(ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i));
				}
				DefaultCast(goBackToDiceTray: false, null, source);
			});
		}
		else
		{
			DefaultCast(goBackToDiceTray: true, null, source);
		}
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		if (diceList.Count == 0)
		{
			for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
			{
				diceList.Add(ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i));
			}
			DefaultCast(goBackToDiceTray: false, target, source);
		}
		else
		{
			DefaultCast(goBackToDiceTray: true, target, source);
		}
	}

	private void DefaultCast(bool goBackToDiceTray, GameObject target, GameObject source)
	{
		int num = 0;
		for (int i = 0; i < diceList.Count; i++)
		{
			bool flag;
			bool flag2 = (flag = false);
			DiceInstance diceInstance = diceList[i];
			if (diceInstance.ActionFace.BattleAction is CorruptAction && diceInstance.ActionFace.ActionValue >= 0)
			{
				num += diceInstance.ActionFace.ModifiedActionValue - finalValue;
				diceInstance.ActionFace.SetActionModifierLock(isLocked: false);
				diceInstance.ActionFace.ActionValue = finalValue;
				flag2 = true;
			}
			if (diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.SecondBattleAction is CorruptAction && diceInstance.ActionFace.SecondActionValue >= 0)
			{
				num += diceInstance.ActionFace.SecondModifiedActionValue - finalValue;
				diceInstance.ActionFace.SetSecondActionModifierLock(isLocked: false);
				diceInstance.ActionFace.SecondActionValue = finalValue;
				flag = true;
			}
			diceInstance.ActionFace.RemoveActionValueModifier(battleActionInteractionEnum);
			if (flag2)
			{
				diceInstance.ActionFace.SetActionModifierLock(isLocked: true);
			}
			if (flag)
			{
				diceInstance.ActionFace.SetSecondActionModifierLock(isLocked: true);
			}
			if (flag2 || flag)
			{
				if (IsVFXEnabled())
				{
					GetVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance);
				}
				diceInstance.UpdateDiceFace();
				SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance);
			}
			if (purificationToPickedDice)
			{
				CheckPurification(num, source, diceList[i].ActionOwner);
				num = 0;
			}
		}
		SpawnSecondVFXOnPlayerPosition(3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		if (!purificationToPickedDice)
		{
			CheckPurification(num, source, target);
		}
		EndAction(goBackToDiceTray);
		ResetVariables();
	}

	private void CheckPurification(int corruptDifference, GameObject source, GameObject target = null)
	{
		if (corruptDifference > 0)
		{
			targetToPurifyLogic.ActivateOmen(purifyAction, corruptDifference * purificationMultiplier, target, source);
		}
	}
}
